<x-app-layout>
<x-slot name="header">Sprints</x-slot>
<div x-data="sprintDashboard({selectedClientId:@js($selectedClientId),canStartSprint:@js($canStartSprint),startUrl:@js(route('sprints.start.store')),sectionsUrl:@js(route('sprints.dashboard-sections')),elapsed:@js($currentSprintStats['elapsed_seconds'] ?? 0),running:@js(($currentSprintStats['timer_status'] ?? null)===\App\Models\Sprint::TIMER_RUNNING),canEndSprint:@js($currentSprintStats['can_end'] ?? false)})" class="space-y-4">
  <div class="flex items-center justify-end gap-2">
    @if($isKielUser)
      <form method="GET"><select name="client_id" onchange="this.form.submit()" class="rounded-lg border border-slate-200 px-2 py-1.5 text-sm"><option value="">Select client</option>@foreach($clients as $c)<option value="{{ $c->id }}" @selected($selectedClientId===$c->id)>{{ $c->name }}</option>@endforeach</select></form>
    @endif
    <button type="button" class="rounded-lg border px-3 py-2 text-sm" @click="openCreateFeatureDrawer()">Feature Request</button>
    <button type="button" class="sprint-icon-button" :disabled="startingSprint||!canStartSprint" :title="!selectedClientId ? 'Select a client before starting a sprint.' : (!canStartSprint ? 'No approved features are ready for this sprint.' : 'Start sprint')" @click="startSprint">▶<span class="sr-only">Start sprint</span></button>
  </div>

  <div id="current-sprint-wrap">@include('sprints.partials.current-sprint')</div>
  <div id="approved-features-wrap">@include('sprints.partials.approved-features-table')</div>
  <div id="future-features-wrap">@include('sprints.partials.future-features-table')</div>
  <div id="history-wrap">@include('sprints.partials.history-table')</div>
  @include('tasks.partials.create-feature-drawer')
  @include('tickets.partials.drawer')
</div>
<script>
function sprintDashboard(c){return{...c,loadingFeatureId:null,startingSprint:false,running:!!c.running,elapsed:c.elapsed||0,tick:null,canEndSprint:!!c.canEndSprint,get formattedTimer(){const s=this.elapsed,h=String(Math.floor(s/3600)).padStart(2,'0'),m=String(Math.floor((s%3600)/60)).padStart(2,'0'),sec=String(s%60).padStart(2,'0');return `${h}:${m}:${sec}`},init(){if(this.running)this.startTick()},startTick(){clearInterval(this.tick);this.tick=setInterval(()=>{if(this.running)this.elapsed++},1000)},createFeatureDrawerOpen:false,createFeatureForm:{title:'',description:'',software_id:'',urgency:'',parent_ticket_id:''},openCreateFeatureDrawer(){this.createFeatureDrawerOpen=true},closeCreateFeatureDrawer(){this.createFeatureDrawerOpen=false},async refreshSections(){const q=this.selectedClientId?`?client_id=${this.selectedClientId}`:'';const d=await window.Kiel.request(`${this.sectionsUrl}${q}`);document.getElementById('current-sprint-wrap').innerHTML=d.current_sprint_html;document.getElementById('approved-features-wrap').innerHTML=d.approved_features_html;document.getElementById('future-features-wrap').innerHTML=d.future_features_html;document.getElementById('history-wrap').innerHTML=d.history_html;this.elapsed=d.stats?.elapsed_seconds||0;this.running=(d.stats?.timer_status==='running');this.canEndSprint=!!d.stats?.can_end;if(this.running)this.startTick();window.Kiel.initializeTicketDrawer?.();},async submitCreateFeature(){try{await window.Kiel.request("{{ route('features.request.store') }}",{method:'POST',body:JSON.stringify(this.createFeatureForm)});window.Kiel.toast('Feature request created.');await this.refreshSections();this.closeCreateFeatureDrawer();}catch(e){window.Kiel.toast(e.message,'error')}},async approveForSprint(id,url){this.loadingFeatureId=id;try{await window.Kiel.request(url,{method:'POST'});window.Kiel.toast('Feature approved for sprint.');await this.refreshSections();}catch(e){window.Kiel.toast(e.message,'error')}finally{this.loadingFeatureId=null}},async removeFromSprint(id,url){this.loadingFeatureId=id;try{await window.Kiel.request(url,{method:'PATCH'});window.Kiel.toast('Feature removed from sprint queue.');await this.refreshSections();}catch(e){window.Kiel.toast(e.message,'error')}finally{this.loadingFeatureId=null}},async startSprint(){if(!this.selectedClientId){window.Kiel.toast('Select a client before starting a sprint.','error');return;}if(!this.canStartSprint){window.Kiel.toast('No approved features are ready for this sprint.','error');return;}this.startingSprint=true;try{await window.Kiel.request(this.startUrl,{method:'POST',body:JSON.stringify({client_id:this.selectedClientId})});window.Kiel.toast('Sprint started.');await this.refreshSections();}catch(e){window.Kiel.toast(e.message,'error')}finally{this.startingSprint=false}},async pauseSprint(id){await window.Kiel.request(`/sprints/${id}/pause`,{method:'PATCH'});this.running=false;window.Kiel.toast('Sprint paused.');await this.refreshSections();},async resumeSprint(id){await window.Kiel.request(`/sprints/${id}/resume`,{method:'PATCH'});this.running=true;window.Kiel.toast('Sprint resumed.');await this.refreshSections();},async endSprint(id){if(!this.canEndSprint){window.Kiel.toast('All sprint tasks must be completed, rejected, or blocked before ending.','error');return;}try{await window.Kiel.request(`/sprints/${id}/end`,{method:'PATCH'});this.running=false;window.Kiel.toast('Sprint ended.');await this.refreshSections();}catch(e){window.Kiel.toast(e.message,'error')}}}}
</script>
</x-app-layout>
